CREATE TABLE IF NOT EXISTS "site_model_context" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "site_id" INTEGER NOT NULL, "model_name" TEXT NOT NULL, "model_name_raw" TEXT, "context_limit" INTEGER, "source" TEXT NOT NULL DEFAULT 'error', "observed_max_prompt" INTEGER, "note" TEXT, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "site_model_context_site_model_unique" ON "site_model_context" ("site_id", "model_name");
CREATE INDEX "site_model_context_site_id_idx" ON "site_model_context" ("site_id");
